# -*- coding: utf-8 -*-
"""Banco de ejercicios UD02 · soluciones revisadas a partir de las hojas de TODO.drawio
y ejercicios nuevos (streaming, vacunas, casas rurales, casas de Juego de Tronos y
grupos del apocalipsis zombi).

Cada entrada lleva una clave `k`. Las que coinciden con un número de ud02_banco_1/2
SUSTITUYEN a ese ejercicio; las demás son nuevas. La numeración final la decide
ORDEN (ver build_banco.py y gen_svgs.py)."""
from chen_eer import *

EJS = []


def ej(**kw):
    EJS.append(kw)


# Orden final del banco (números antiguos o claves nuevas) y bloques.
ORDEN = [
    # Bloque 1 · Fundamentos
    1, "streaming", 3, 2, 4,
    # Bloque 2 · Intermedio
    5, 6, "vacunas", 7, 8, "rurales", 9, 10, 11, 12,
    # Bloque 3 · Integración
    13, 14, 15, 16, 17, 18, "got", 19,
    # Bloque 4 · EER avanzado
    20, 21, 22, 23, 24, "zombis", 25,
]
TAM_BLOQUES = [5, 10, 8, 7]


# ------------------------------------------------------------------ 4 · Parentesco (revisado)
ej(k=4, titulo="Parentesco y filiación", nivel=1, dur="1 sesión",
   ra="RA6: d, h", entrega="Diagrama EER + análisis del enunciado",
   objetivo="Modelar una relación **reflexiva** con roles, detectar una cardinalidad mínima imposible y fijar un máximo concreto (2).",
   contexto="Un registro genealógico quiere guardar quién es progenitor de quién.",
   enun=["Se desea diseñar una base de datos que registre las relaciones de parentesco entre **personas**. De cada persona se conocen el DNI, el nombre, la dirección y el teléfono.",
         "Una persona puede ser progenitora (padre o madre) de varios hijos o hijas, o de ninguno. Toda persona registrada en el sistema debe tener registrada obligatoriamente su filiación directa con su progenitor o progenitora."],
   tareas=["Dibuja el diagrama EER con una **relación reflexiva** y los **roles** (progenitor, hijo).",
           "Escribe las cardinalidades (mín, máx) de cada rol. ¿Cuántos progenitores puede tener una persona como máximo?",
           "Razona si el mínimo que pide el enunciado («obligatoriamente») se puede mantener en una base de datos real y propón uno viable.",
           "Colorea el rombo según la notación del módulo y explica por qué queda entero en negro."],
   comp=["Solo hay una entidad y la relación sale y vuelve a ella.",
         "Los dos extremos de la relación tienen **rol**.",
         "El máximo del rol *progenitor* es **2** (padre y madre), no 1 ni N.",
         "Has detectado el problema de las personas sin ascendientes registrados y el mínimo del rol *progenitor* es 0."],
   err=["Crear dos entidades `PADRE` e `HIJO`. Ambos son `PERSONA` y una persona puede ser a la vez padre e hijo.",
        "Poner (1,1) en el rol de progenitor: solo permitiría registrar a uno de los dos progenitores y, además, obligaría a que todas las personas tuvieran uno registrado.",
        "Dibujar el rombo mitad blanco y mitad negro: los dos máximos (2 y N) son mayores que 1, así que las dos mitades van en negro."],
   pista=("Pista: ¿quién es el primer antepasado?",
          "Si todas las personas deben tener progenitor registrado y la base de datos es finita, la cadena de ascendientes tendría que cerrarse en un ciclo. Esto es imposible. El mínimo del rol *progenitor* tiene que ser 0."),
   amp="Se quiere distinguir la filiación **biológica** de la **adoptiva** y registrar la fecha de adopción. ¿Dónde colocas esos atributos? ¿Sigue siendo 2 el máximo del rol *progenitor*?",
   dec=["*Tiene hijos* es una relación reflexiva **N:M**: una persona tiene hasta 2 progenitores registrados y puede tener muchos hijos. Por eso el rombo es negro entero.",
        "El enunciado pide que la filiación sea obligatoria (mínimo 1), pero eso es insostenible: se corrige a **(0,2)** y se documenta como restricción de negocio (RA6.h).",
        "El máximo 2 es una cardinalidad concreta: se escribe tal cual en el diagrama. Al pasar al modelo relacional (UD03) no se puede controlar solo con claves; necesitará un `CHECK` o un disparador.",
        "Los roles distinguen los dos extremos de la misma entidad."],
   sup=["Las personas fundadoras del árbol no tienen progenitor registrado: mínimo 0.",
        "Una persona tiene como máximo dos progenitores registrados (padre y madre).",
        "Una persona no puede ser progenitora de sí misma ni de sus ascendientes (restricción que el diagrama no recoge)."],
   model=Model("Parentesco y filiación",
               "PERSONA tiene hijos PERSONA: relación reflexiva N:M con los roles progenitor (0,2) e hijo (0,N).",
               [E("PERSONA", [K("dni"), A("nombre"), A("dirección"), A("teléfono")])],
               [R("tiene hijos", [("PERSONA", "(0,2)", "progenitor"), ("PERSONA", "(0,N)", "hijo")])]))

# ------------------------------------------------------------------ 5 · Instituto (revisado)
ej(k=5, titulo="Instituto: módulos, matrículas, delegados y casilleros", nivel=2, dur="1 sesión",
   ra="RA6: a, d, e, h", entrega="Diagrama EER + restricciones textuales",
   objetivo="Distinguir una relación 1:1 opcional, una N:M reflexiva y una 1:N reflexiva en un mismo modelo.",
   contexto="Un instituto de Educación Secundaria y Formación Profesional diseña su base de datos de docencia.",
   enun=["De los **profesores** se guarda el DNI, el nombre, la dirección y el teléfono. Los profesores imparten **módulos**, cada uno con un código y un nombre. Un profesor puede impartir varios módulos, pero cada módulo lo imparte un único profesor.",
         "Algunos módulos tienen como **prerrequisito** haber cursado otros. Un módulo puede exigir varios módulos previos y, a su vez, ser requisito de otros.",
         "De cada **alumno** se almacena el número de expediente, el nombre, los apellidos, la fecha de nacimiento y el curso. Un alumno se matricula en uno o varios módulos y se registra la fecha de matriculación.",
         "Cada curso cuenta con un grupo de alumnos. Dentro de cada grupo se elige a uno de ellos como **delegado**, que representa a sus compañeros.",
         "Los alumnos que lo soliciten pueden disponer de un **casillero** (número y tamaño en metros). Un casillero pertenece a un único alumno y un alumno tiene como máximo un casillero."],
   tareas=["Dibuja el diagrama EER en notación de Chen.",
           "Modela al delegado **sin crear una entidad nueva**. ¿Qué tipo de relación necesitas? Escribe sus roles.",
           "Calcula las cardinalidades de la relación con el casillero y razona por qué el mínimo es 0 en los dos lados.",
           "Escribe al menos **dos restricciones** que el diagrama no puede expresar."],
   comp=["*Es requisito de* es una N:M **reflexiva** sobre `MÓDULO` con dos roles.",
         "*Es delegado de* es una 1:N **reflexiva** sobre `ALUMNO`.",
         "La relación alumno–casillero es 1:1 con (0,1) en los dos lados: el rombo es blanco entero.",
         "`fecha_matrícula` está en la relación *se matricula*, no en `ALUMNO`."],
   err=["Usar un atributo `es_delegado` en `ALUMNO`: no dice a quién representa ni garantiza un único delegado por grupo.",
        "Dibujar *es requisito de* como 1:N. Un módulo puede tener varios previos y ser previo de varios.",
        "Poner la fecha de matrícula en `ALUMNO`: un alumno se matricula de varios módulos, quizá en fechas distintas."],
   pista=("Pista: el delegado también es un alumno",
          "Cuando una entidad se relaciona consigo misma se usa una **relación reflexiva**. Un alumno (rol *delegado*) representa a muchos alumnos (rol *representado*) y cada alumno tiene, como mucho, un delegado."),
   amp="El centro decide guardar los **grupos** como entidad (código, curso, aula). Rediseña la parte del delegado: ¿qué relaciones aparecen entre `ALUMNO` y `GRUPO`? ¿Por qué no pueden fusionarse en una sola?",
   dec=["*Imparte* es 1:N; *se matricula* es N:M con atributo; *es requisito de* es N:M reflexiva.",
        "*Es delegado de* es una reflexiva 1:N: un alumno delegado representa a (0,N) compañeros y cada alumno tiene (0,1) delegado (0 mientras no se haya elegido).",
        "*Tiene* (casillero) es 1:1 con mínimos 0: no todos los alumnos piden casillero y puede haber casilleros libres. Este caso, con (0,1) en los dos lados, se transforma en la UD03 con una tabla propia.",
        "El curso es un atributo de `ALUMNO`. Si el grupo tuviera más datos, pasaría a ser una entidad (ver ampliación)."],
   sup=["Todo módulo tiene profesor asignado: (1,1).",
        "Un alumno matriculado lo está al menos de un módulo: (1,N).",
        "El delegado y sus representados son del mismo curso (restricción textual).",
        "Un módulo no puede ser prerrequisito de sí mismo ni formar ciclos (restricción textual)."],
   model=Model("Instituto: módulos, matrículas, delegados y casilleros",
               "PROFESOR imparte MÓDULO (1:N); MÓDULO es requisito de MÓDULO (N:M reflexiva); ALUMNO se matricula en MÓDULO (N:M con fecha); ALUMNO es delegado de ALUMNO (1:N reflexiva); ALUMNO tiene CASILLERO (1:1).",
               [E("PROFESOR", [K("dni"), A("nombre"), A("dirección"), A("teléfono")]),
                E("MÓDULO", [K("código"), A("nombre")]),
                E("ALUMNO", [K("nº_expediente"), A("nombre"), A("apellidos"), A("fecha_nacimiento"), A("curso")]),
                E("CASILLERO", [K("nº_casillero"), A("tamaño_m")])],
               [R("imparte", [("PROFESOR", "(1,1)", None), ("MÓDULO", "(1,N)", None)]),
                R("es requisito de", [("MÓDULO", "(0,N)", "previo"), ("MÓDULO", "(0,N)", "posterior")]),
                R("se matricula", [("ALUMNO", "(0,N)", None), ("MÓDULO", "(1,N)", None)], [A("fecha_matrícula")]),
                R("es delegado de", [("ALUMNO", "(0,1)", "delegado"), ("ALUMNO", "(0,N)", "representado")]),
                R("tiene", [("ALUMNO", "(0,1)", None), ("CASILLERO", "(0,1)", None)])]))

# ------------------------------------------------------------------ streaming (nuevo)
ej(k="streaming", titulo="Películas en streaming", nivel=1, dur="1 sesión",
   ra="RA6: a, d, e", entrega="Diagrama EER + supuestos",
   objetivo="Convertir en entidades los datos por los que se busca (actor, género) y descubrir que un hecho («haber visto») es una relación, no un atributo booleano.",
   contexto="Una plataforma de cine bajo demanda quiere recomendar películas y avisar al cliente de lo que ya ha visto.",
   enun=["Se desea crear una base de datos para una plataforma de películas en *streaming*.",
         "A los **clientes** se les piden sus datos personales (NIF, nombre, apellidos, correo electrónico y dirección) y el sistema mantiene el **saldo** disponible de su cuenta.",
         "Los clientes pueden buscar **películas** por **género**, por **actores** y por título. De cada película se guarda un código, el título, el año de estreno y la duración en minutos. De los actores se conoce un código, el nombre completo y la nacionalidad. Cada película pertenece a un género (comedia, drama, terror…).",
         "La plataforma debe avisar al cliente si una película **ya la ha visto**. Para ello registra qué películas ha visto cada cliente, la fecha y la valoración (de 1 a 5) que le ha dado."],
   tareas=["Dibuja el diagrama EER en notación de Chen.",
           "Explica por qué `ACTOR` y `GÉNERO` son entidades y no atributos de `PELÍCULA`.",
           "¿Hace falta un atributo `vista (sí/no)`? Razona la respuesta.",
           "Anota los supuestos."],
   comp=["Hay cuatro entidades: `CLIENTE`, `PELÍCULA`, `ACTOR` y `GÉNERO`.",
         "*Ve* es N:M y lleva `fecha` y `valoración`.",
         "*Actúa en* es N:M y *pertenece a* es 1:N.",
         "No existe ningún atributo booleano «vista»."],
   err=["Añadir `vista (sí/no)` a la relación: si existe la pareja cliente–película, ya la ha visto; si no existe, no. El booleano es redundante.",
        "Guardar `actor` y `género` como atributos de `PELÍCULA`: una película tiene varios actores y buscar por ellos obligaría a recorrer texto libre.",
        "Poner el `saldo` en una entidad aparte: es un dato de cada cliente."],
   amp="Una película puede pertenecer a **varios géneros** (comedia romántica, terror psicológico…). ¿Qué cambia en la relación *pertenece a*? ¿Y en el color del rombo?",
   dec=["*Ve* es **N:M** con `fecha` y `valoración`: la existencia de la pareja (cliente, película) ya indica que la ha visto. Si se quiere guardar cada visionado, la fecha pasa a formar parte de la identificación (subrayado discontinuo).",
        "*Actúa en* es N:M: un actor participa en muchas películas y una película tiene muchos actores.",
        "*Pertenece a* es 1:N: cada película tiene un género y un género agrupa muchas películas. El rombo tiene la mitad blanca junto a `GÉNERO` (máximo 1) y la negra junto a `PELÍCULA` (máximo N)."],
   sup=["Un cliente puede no haber visto ninguna película todavía: (0,N).",
        "Toda película tiene al menos un actor registrado: (1,N).",
        "Se guarda cada visionado, de modo que un cliente puede ver la misma película en fechas distintas.",
        "La valoración es un entero entre 1 y 5 (restricción de dominio)."],
   model=Model("Películas en streaming",
               "CLIENTE ve PELÍCULA (N:M con fecha y valoración). ACTOR actúa en PELÍCULA (N:M). PELÍCULA pertenece a GÉNERO (N:1).",
               [E("CLIENTE", [K("nif"), A("nombre"), A("apellidos"), A("email"), A("dirección"), A("saldo")]),
                E("PELÍCULA", [K("cód_película"), A("título"), A("año_estreno"), A("duración_min")]),
                E("ACTOR", [K("cód_actor"), A("nombre"), A("nacionalidad")]),
                E("GÉNERO", [K("cód_género"), A("nombre")])],
               [R("ve", [("CLIENTE", "(0,N)", None), ("PELÍCULA", "(0,N)", None)], [KP("fecha"), A("valoración")]),
                R("actúa en", [("ACTOR", "(1,N)", None), ("PELÍCULA", "(0,N)", None)]),
                R("pertenece a", [("PELÍCULA", "(0,N)", None), ("GÉNERO", "(1,1)", None)])]))

