ej(k="vacunas", titulo="Clínica veterinaria: calendario de vacunación", nivel=2, dur="1 sesión",
   ra="RA6: a, d, e, h", entrega="Diagrama EER + supuestos",
   objetivo="Separar los datos que se **calculan** (edad, próxima vacuna) de los que se guardan y evitar relaciones redundantes.",
   contexto="Una clínica veterinaria quiere avisar a los dueños de las vacunas pendientes de sus animales.",
   enun=["Queremos crear una base de datos para una clínica veterinaria con el fin de controlar el calendario de vacunación de los animales y avisar al dueño cuándo debe acudir a la clínica.",
         "De cada **cliente** (dueño) se guardan el DNI, el nombre, los apellidos, la dirección, el teléfono y el correo electrónico. Un cliente puede tener varios animales.",
         "De cada **animal** se conoce un código, el nombre, el tipo (perro, gato…), la raza y la fecha de nacimiento; también se quiere mostrar su edad.",
         "De cada **vacuna** se guarda un código, el nombre y cada cuántos días hay que repetirla. Cuando se administra una vacuna a un animal se registra la fecha; la próxima fecha de vacunación se calcula a partir de la última administración y del tipo de vacuna.",
         "La clínica envía **notificaciones**: de cada una se guarda un número, la fecha de envío, la vacuna pendiente y la fecha prevista de administración.",
         "Se registran también las **visitas** de cada animal: fecha, tipo de visita (vacunación, consulta…) y notas."],
   tareas=["Dibuja el diagrama EER en notación de Chen.",
           "Marca los atributos **derivados** y explica de qué datos se obtienen.",
           "¿Debe relacionarse `NOTIFICACIÓN` directamente con `CLIENTE`? Razona la respuesta.",
           "Decide si `VISITA` es una entidad débil y escribe su identificador completo."],
   comp=["`edad` y `próxima_fecha` son derivados (óvalo discontinuo).",
         "*Se vacuna* es N:M entre `ANIMAL` y `VACUNA` y la fecha permite repetir la misma vacuna.",
         "`NOTIFICACIÓN` se relaciona con `ANIMAL` y con `VACUNA`, no con `CLIENTE`.",
         "`VISITA` es débil de `ANIMAL` (etiqueta ID)."],
   err=["Guardar la edad: cambia cada día. Se calcula a partir de la fecha de nacimiento.",
        "Guardar «tipo de vacuna pendiente» como texto en la notificación: debe ser una relación con `VACUNA`.",
        "Relacionar la notificación con el cliente **y** con el animal: el dueño se obtiene a partir del animal, y las dos relaciones podrían contradecirse."],
   amp="Algunas vacunas se ponen **durante una visita**. ¿Cómo relacionarías la administración de la vacuna con la visita? ¿Qué problema aparece si una visita incluye dos vacunas?",
   dec=["*Es dueño de* es 1:N: cada animal tiene un único dueño registrado.",
        "*Se vacuna* es N:M con `fecha` como discriminador (una vacuna se repite cada cierto tiempo) y `próxima_fecha` como atributo derivado.",
        "`NOTIFICACIÓN` es una entidad con identificador propio relacionada 1:N con `ANIMAL` y con `VACUNA`; el cliente se deduce del animal.",
        "`VISITA` es débil: se identifica por (código del animal, fecha)."],
   sup=["Todo animal tiene dueño: (1,1).",
        "Un animal no recibe dos veces la misma vacuna el mismo día.",
        "Un animal no tiene dos visitas en la misma fecha.",
        "La próxima fecha = última administración + periodicidad de la vacuna (regla de cálculo)."],
   model=Model("Clínica veterinaria: calendario de vacunación",
               "CLIENTE es dueño de ANIMAL (1:N). ANIMAL se vacuna con VACUNA (N:M con fecha). NOTIFICACIÓN avisa de VACUNA y se envía por ANIMAL. ANIMAL tiene VISITA (débil).",
               [E("CLIENTE", [K("dni"), A("nombre"), A("apellidos"), A("dirección"), A("teléfono"), A("email")]),
                E("ANIMAL", [K("cód_animal"), A("nombre"), A("tipo"), A("raza"), A("fecha_nacimiento"), D("edad")]),
                E("VACUNA", [K("cód_vacuna"), A("nombre"), A("periodicidad_días")]),
                E("NOTIFICACIÓN", [K("nº_notificación"), A("fecha_envío"), A("fecha_prevista")]),
                E("VISITA", [KP("fecha"), A("tipo"), A("notas")], weak=True)],
               [R("es dueño de", [("CLIENTE", "(1,1)", None), ("ANIMAL", "(1,N)", None)]),
                R("se vacuna", [("ANIMAL", "(0,N)", None), ("VACUNA", "(0,N)", None)], [KP("fecha"), D("próxima_fecha")]),
                R("avisa de", [("NOTIFICACIÓN", "(0,N)", None), ("VACUNA", "(1,1)", None)]),
                R("se envía por", [("ANIMAL", "(1,1)", None), ("NOTIFICACIÓN", "(0,N)", None)]),
                R("pasa", [("ANIMAL", "(1,1)", None), ("VISITA", "(0,N)", None)], ident=True)]))

