ej(k="zombis", titulo="Grupos de supervivientes del apocalipsis zombi", nivel=3, dur="2 sesiones",
   ra="RA6: a, d, e, h", entrega="Diagrama EER + clasificación de la jerarquía + restricciones",
   objetivo="Combinar una especialización con atributos propios, un atributo derivado, una entidad débil y una reflexiva sobre la entidad débil.",
   contexto="Año 2050: tras una invasión zombi, los supervivientes se organizan en grupos y el informático superviviente quiere una base de datos con ellos.",
   enun=["Se necesita almacenar información sobre cada **grupo**, los **integrantes** que lo componen, las **tareas** (proyectos) que realiza y sus **trabajadores**.",
         "De los grupos se guarda el identificador, la denominación, la dirección, la provincia y el tipo (recolectores, creadores de munición, atacantes…).",
         "Cada grupo está formado por integrantes, de los que se conoce el DNI, el nombre, la dirección, la provincia, la fecha de alta en el grupo, la cuota mensual con que colaboran y la aportación anual (que se obtiene multiplicando la cuota mensual por los meses del año).",
         "Los grupos tienen también **trabajadores**. Cada trabajador se identifica por un ID y tiene un nombre y una fecha de ingreso. Los trabajadores son de dos tipos: **mantenidos**, que cobran un sueldo en especie y ocupan un cargo (se guarda la cantidad total que se les ha dado), y **voluntarios**, de los que se guarda la edad, la profesión y las horas que dedican al grupo. Un integrante no puede ser trabajador del grupo.",
         "Los grupos realizan **tareas**. Cada tarea se identifica por un número **dentro del grupo** y se guarda en qué zona libre de zombis se realiza y en qué parte de ella, el objetivo y el número de beneficiarios. Una tarea se compone a su vez de **subtareas**, que también son tareas."],
   tareas=["Dibuja el diagrama EER en notación de Chen.",
           "Clasifica la especialización de `TRABAJADOR` y justifícala.",
           "Indica qué atributo es derivado y cómo se calcula.",
           "Modela las subtareas y escribe el identificador completo de `TAREA`.",
           "Escribe las restricciones que el diagrama no puede expresar."],
   comp=["`TRABAJADOR` se especializa en `MANTENIDO` y `VOLUNTARIO` con **T,D**.",
         "`aportación_anual` es derivado (óvalo discontinuo).",
         "`TAREA` es débil de `GRUPO` (etiqueta ID).",
         "*Se compone de* es una reflexiva 1:N sobre `TAREA`."],
   err=["Crear una entidad `SUBTAREA`: una subtarea es una tarea, se modela con una relación reflexiva.",
        "Guardar la aportación anual: se calcula como `cuota_mensual × 12`.",
        "Poner `edad` y `profesión` en `TRABAJADOR`: solo los tienen los voluntarios."],
   amp="Un integrante puede pertenecer a **varios grupos** con una cuota distinta en cada uno. ¿Qué cambia en la relación *forma parte de*? ¿Dónde van ahora `fecha_alta`, `cuota_mensual` y `aportación_anual`?",
   dec=["Especialización **total y disjunta**: todo trabajador es mantenido o voluntario, nunca ambos.",
        "*Forma parte de* y *trabaja en* son 1:N con `GRUPO`.",
        "`TAREA` se identifica por (id del grupo, nº de tarea). *Se compone de* es reflexiva 1:N con los roles *tarea* y *subtarea*.",
        "«Un integrante no puede ser trabajador» no se representa en el diagrama: integrantes y trabajadores son entidades distintas con identificadores distintos. Se documenta como restricción textual."],
   sup=["Todo integrante pertenece a un grupo: (1,1).",
        "Una subtarea pertenece al mismo grupo que su tarea (restricción textual).",
        "Una persona no puede ser a la vez integrante y trabajador (restricción textual).",
        "Las horas de los voluntarios son un número positivo."],
   model=Model("Grupos de supervivientes del apocalipsis zombi",
               "INTEGRANTE forma parte de GRUPO. TRABAJADOR trabaja en GRUPO y se especializa (T,D) en MANTENIDO y VOLUNTARIO. GRUPO realiza TAREA (débil). TAREA se compone de TAREA.",
               [E("GRUPO", [K("id_grupo"), A("denominación"), A("dirección"), A("provincia"), A("tipo")]),
                E("INTEGRANTE", [K("dni"), A("nombre"), A("dirección"), A("provincia"), A("fecha_alta"), A("cuota_mensual"), D("aportación_anual")]),
                E("TRABAJADOR", [K("id_trabajador"), A("nombre"), A("fecha_ingreso")]),
                E("MANTENIDO", [A("cargo"), A("cantidad_total")]),
                E("VOLUNTARIO", [A("edad"), A("profesión"), A("horas")]),
                E("TAREA", [KP("nº_tarea"), A("zona_libre"), A("zona"), A("objetivo"), A("nº_beneficiarios")], weak=True)],
               [R("forma parte de", [("GRUPO", "(1,1)", None), ("INTEGRANTE", "(1,N)", None)]),
                R("trabaja en", [("GRUPO", "(1,1)", None), ("TRABAJADOR", "(0,N)", None)]),
                R("realiza", [("GRUPO", "(1,1)", None), ("TAREA", "(0,N)", None)], ident=True),
                R("se compone de", [("TAREA", "(0,1)", "tarea"), ("TAREA", "(0,N)", "subtarea")])],
               [ISA("TRABAJADOR", ["MANTENIDO", "VOLUNTARIO"], "d", True)]))
